-- Supabase SQL: QA dataset with neural semantic embeddings.
-- Model: sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2 (multilingual, 384 dimensions).
-- Each embedding is generated from question + answer; use the same model for search queries.
-- If public.qa already exists with vector(512), recreate that table before applying this fresh-schema script.
create extension if not exists vector with schema extensions;

create table if not exists public.qa (
    question text not null,
    answer text not null,
    embedding extensions.vector(384) not null
);

comment on column public.qa.embedding is
    'sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2; neural network semantic embedding of question and answer (384D)';


create index if not exists qa_embedding_hnsw_idx
    on public.qa using hnsw (embedding vector_cosine_ops);
